              }
              let ssh_detail = if message.contains("timed out") {
                if @fs.exists(directory + "/ssh-error.json") {
                  let event = @json.parse(
                    @fs.read_file(directory + "/ssh-error.json").text(),
                  ) catch {
                    _ => Json::null()
                  }
                  optional_text(event, "detail")
                } else {
                  "SSH failure details unavailable"
      } else if worker_alive(directory) {
