///|
async fn cleanup_server_update(state : Json) -> Unit {
  let directory = required(state, "tunnelDirectory")
  ignore(
    update_remote(
      state, "base=\"$HOME/.local/share/orca-env-devsy/orca\"; rm -rf \"$base/update-previous\" \"$base/update-retry\"",
      "server-update-cleanup",
    ),
  )
  @fs.remove(directory + "/server-update-complete")
}

///|
async fn update_one_server(
  state : Json,
  provider : String,
  version : String,
  force : Bool,
) -> Json {
  let directory = required(state, "tunnelDirectory")
  let result : Json = {
    "id": required(state, "workspaceId"),
    "provider": provider,
    "context": required(state, "context"),
    "targetVersion": version,
    "outcome": "failed",
  }
  let mut phase = "identity"
  try {
    let operation = connection_operation_lock(state)
    defer operation.close()
    let current = workspace(state)
    guard current is Some(current) &&
      field(current, "uid") == field(state, "workspaceUid") &&
      field(field(current, "provider").unwrap_or(Json::null()), "name") ==
      Some(Json::string(provider)) else {
      raise AdapterError(
        "Workspace is missing, replaced, or has a different provider",
      )
    }
    phase = "workspace-status"
    let status = workspace_status(state)
    set_field(result, "workspaceStatus", Json::string(status))
    if status == "Stopped" {
      set_field(result, "outcome", Json::string("skipped"))
      set_field(result, "reason", Json::string("workspace_stopped"))
      save_diagnostic(
        "server-update",
        "skipped",
        evidence=result,
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
      return result
    }
    guard status == "Running" else {
      raise AdapterError("Workspace is not running")
    }
    phase = "transport"
    ensure_ssh_worker(state, Some(reserve_server_port(state)))
    let lock = @fs.open(
      directory + "/server.lock",
      mode=ReadWrite,
      create_mode=OpenOrCreate,
      permission=0o600,
    )
    defer lock.close()
    @async.with_timeout(30000, async fn() {
      while !lock.try_lock(Exclusive) {
        @async.sleep(100)
      }
    })
    if @fs.exists(directory + "/server-update-complete") {
      cleanup_server_update(state)
    }
    let pending = @fs.exists(directory + "/server-update-pending")
    set_field(result, "retry", Json::boolean(pending))
    phase = "version"
    let installed = update_remote(
        state, "base=\"$HOME/.local/share/orca-env-devsy/orca\"; dir=\"$base/current\"; if test ! -x \"$dir/orca-ide\"; then dir=\"$base/update-previous\"; fi; ELECTRON_RUN_AS_NODE=1 \"$dir/orca-ide\" \"$dir/resources/app.asar/out/cli/index.js\" --version",
        "server-update-version",
      )
      .trim()
      .to_owned()
    ignore(server_version(installed))
    set_field(result, "previousVersion", Json::string(installed))
    if server_version_is_older(version, installed) && !force {
      raise AdapterError("Server downgrade requires --force")
    }
    phase = "prepare"
    if !pending {
      ignore(
        update_remote(
          state, "test ! -e \"$HOME/.local/share/orca-env-devsy/orca/update-previous\" && test ! -e \"$HOME/.local/share/orca-env-devsy/orca/update-retry\"",
          "server-update-ownership",
        ),
      )
    }
    ignore(
      update_remote(
        state,
        server_update_prepare_script(version),
        "server-update-prepare",
      ),
    )
    phase = "identity-recheck"
    let current = workspace(state)
    guard current is Some(current) &&
      field(current, "uid") == field(state, "workspaceUid") &&
      field(field(current, "provider").unwrap_or(Json::null()), "name") ==
      Some(Json::string(provider)) &&
      workspace_status(state) == "Running" else {
      raise AdapterError("Workspace changed before Server update")
    }
    @fs.write_file(
      directory + "/server-update-pending",
      version,
      permission=0o600,
    )
    phase = "stop"
    ignore(
      update_remote(
        state,
        server_update_process_script(required(state, "projectRoot")),
        "server-update-stop",
      ),
    )
    phase = "switch"
    ignore(
      update_remote(
        state,
        server_update_swap_script(version),
        "server-update-switch",
      ),
    )
    phase = "start"
    let launch_id = version +
      ":" +
      recording_run_id +
      ":" +
      required(state, "workspaceUid")
    let mut marker_name = "ORCA_ENV_DEVSY_UPDATE_" + recording_run_id
    while field(
            field(state, "serverEnv").unwrap_or(Json::empty_object()),
            marker_name,
          )
          is Some(_) {
      marker_name = marker_name + "_"
    }
    ignore(launch_server(state, update_marker=(marker_name, launch_id)))
    phase = "verify"
    let actual = update_remote(
        state, "base=\"$HOME/.local/share/orca-env-devsy/orca/current\"; ELECTRON_RUN_AS_NODE=1 \"$base/orca-ide\" \"$base/resources/app.asar/out/cli/index.js\" --version",
        "server-update-verify-version",
      )
      .trim()
      .to_owned()
    guard actual == version else {
      raise AdapterError("Updated Server version does not match Desktop")
    }
    @async.with_timeout(15000, async fn() {
      while !server_is_running(state) {
        @async.sleep(200)
      }
    })
    ignore(
      update_remote(
        state,
        server_update_process_script(
          required(state, "projectRoot"),
          version=marker_name + "=" + launch_id,
        ),
        "server-update-verify-owner",
      ),
    )
    phase = "commit"
    @fs.rename(
      directory + "/server-update-pending",
      directory + "/server-update-complete",
      replace=true,
    )
    cleanup_server_update(state) catch {
      error =>
        set_field(
          result,
          "cleanupWarning",
          Json::string(redact_credentials(error.to_string())),
        )
    }
    set_field(result, "outcome", Json::string("success"))
    save_diagnostic(
      "server-update",
      "success",
      evidence=result,
      tunnel_directory=directory,
      recording=workspace_recording(state),
    )
  } catch {
    error => {
      set_field(result, "phase", Json::string(phase))
      set_field(
        result,
        "error",
        Json::string(redact_credentials(error.to_string())),
      )
      set_field(
        result,
        "recoverySuppressed",
        Json::boolean(@fs.exists(directory + "/server-update-pending")),
      )
      save_diagnostic(
        "server-update",
        "failed",
        phase~,
        error_type="server_update_failed",
        evidence=result,
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
    }
  }
  result
}

///|
pub async fn update_server(args : Array[String]) -> Unit {
  let options = server_update_options(args)
  let version = desktop_orca_version()
  let base = adapter_state_home() + "/tunnels"
  let states : Array[Json] = []
  let errors : Array[Json] = []
  let results : Array[Json] = []
  let discovery_counts : Map[String, Int32] = Map([])
  if @fs.exists(base) {
    for name in @fs.readdir(base, sort=true) {
      let directory = base + "/" + name
      let mut discovery_phase = "kind"
      try {
        if @fs.kind(directory, follow_symlink=false) != @fs.FileKind::Directory ||
          !@fs.exists(directory + "/enabled") {
          continue
        }
        discovery_phase = "read"
        let raw = @fs.read_file(directory + "/state.json").text()
        discovery_phase = "parse"
        let state = @json.parse(raw)
        if options.workspace is Some(id) &&
          field(state, "workspaceId") is Some(Json::String(saved_id)) &&
          saved_id != id {
          continue
        }
        discovery_phase = "validate"
        validate_state(state)
        if field(state, "connection") != Some(Json::string("orca-server")) {
          continue
        }
        if options.workspace is Some(id) &&
          field(state, "workspaceId") != Some(Json::string(id)) {
          continue
        }
        ignore(required(state, "workspaceUid"))
        ignore(required(state, "context"))
        set_field(state, "tunnelDirectory", Json::string(directory))
        states.push(state)
      } catch {
        error => {
          let kind = discovery_phase +
            ":" +
            process_error_type(error.to_string())
          discovery_counts.set(
            kind,
            discovery_counts.get(kind).unwrap_or(0) + 1,
          )
          errors.push({
            "savedState": directory,
            "error": redact_credentials(error.to_string()),
          })
        }
      }
    }
  }
  let batch_recording = errors.is_empty() &&
    states.iter().all(workspace_recording)
  save_diagnostic(
    "server-update-batch",
    "started",
    evidence={
      "provider": options.provider.map(Json::string).unwrap_or(Json::null()),
      "workspace": options.workspace.map(Json::string).unwrap_or(Json::null()),
      "force": options.force,
      "targetVersion": version,
    },
    recording=batch_recording &&
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
  )
  if !batch_recording && !errors.is_empty() {
    let classes : Array[Json] = []
    for (kind, count) in discovery_counts {
      classes.push({ "class": kind, "count": count })
    }
    save_diagnostic(
      "server-update-discovery",
      "failed",
      error_type="saved_state_invalid",
      evidence={ "classes": classes },
    )
  }
  let keys : Map[String, Int32] = Map([])
  for state in states {
    let key = required(state, "context") + ":" + required(state, "workspaceUid")
    keys.set(key, keys.get(key).unwrap_or(0) + 1)
  }
  let selected : Array[(Json, String)] = []
  for state in states {
    try {
      let key = required(state, "context") +
        ":" +
        required(state, "workspaceUid")
      guard keys.get(key) == Some(1) else {
        raise AdapterError("Duplicate saved workspace identity")
      }
      let current = workspace(state)
      guard current is Some(current) else {
        raise AdapterError("Workspace is missing")
      }
      let provider = required(
        field(current, "provider").unwrap_or(Json::null()),
        "name",
      )
      if options.provider is Some(filter) && provider != filter {
        continue
      }
      selected.push((state, provider))
    } catch {
      error =>
        errors.push({
          "workspace": required(state, "workspaceId"),
          "error": redact_credentials(error.to_string()),
        })
    }
  }
  if options.workspace is Some(_) && selected.length() != 1 {
    errors.push({ "error": "Workspace selection is missing or ambiguous" })
  }
  if options.workspace is None || (selected.length() == 1 && errors.is_empty()) {
    for (state, provider) in selected {
      results.push(update_one_server(state, provider, version, options.force))
    }
  }
  let failed = results
    .filter(row => field(row, "outcome") == Some(Json::string("failed")))
    .length() +
    errors.length()
  let output : Json = {
    "schemaVersion": 1,
    "action": "update",
    "targetVersion": version,
    "workspaces": results,
    "errors": errors,
    "failed": failed,
  }
  @stdio.stdout.write(output.stringify(indent=2) + "\n")
  save_diagnostic(
    "server-update-batch",
    if failed == 0 {
      "success"
    } else {
      "failed"
    },
    evidence=output,
    recording=batch_recording &&
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
  )
  guard failed == 0 else { raise AdapterError("Some Server updates failed") }
}
///|
async fn server_connection(
  state : Json,
  install : Bool,
  deadline? : UInt64,
) -> Json {
  if install {
    let script = server_install_script()
    ignore(remote(state, script, "orca-install"))
    prepare_orca_storage(state)
    initialize_orca_settings(state)
  }
  let output = recover_server(state, connection_result=true)
  ensure_ssh_worker(state, Some(reserve_server_port(state)), deadline?)
  output
}

///|
async fn server_relay_check(
  state : Json,
  mode : String,
  stage : String,
) -> String {
  let output = remote(
    state,
    server_update_locked(
      server_update_process_script(
        required(state, "projectRoot"),
        relay_mode=mode,
      ),
    ),
    stage,
  )
  let result = @json.parse(output)
  let outcome = required(result, "outcome")
  guard ["match", "mismatch", "skip", "restart"].contains(outcome) else {
    raise AdapterError("Invalid Orca Server relay comparison")
  }
  let progress = Progress::new(
    "server-relay-sync",
    environment=workspace_environment(state),
  )
  let evidence : Json = { "outcome": outcome }
  for name in ["serverInstance", "relayInstance"] {
    match field(result, name) {
      Some(Json::String(value)) =>
        set_field(
          evidence,
          name,
          Json::string(progress.safe_message(value).unwrap_or("[unavailable]")),
        )
      _ => set_field(evidence, name, Json::null())
    }
  }
  save_diagnostic(
    "server-relay-sync",
    outcome,
    evidence~,
    tunnel_directory=required(state, "tunnelDirectory"),
    recording=workspace_recording(state),
  )
  outcome
}

///|
async fn recover_server(
  state : Json,
  connection_result~ : Bool = false,
) -> Json {
  let directory = required(state, "tunnelDirectory")
  let lock = @fs.open(
    directory + "/server.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  @async.with_timeout(30000, async fn() {
    while !lock.try_lock(Exclusive) {
      @async.sleep(100)
    }
  })
  guard @fs.exists(directory + "/enabled") && !@fs.exists(directory + "/paused") else {
    raise AdapterError("Connection recovery cancelled")
  }
  guard !@fs.exists(directory + "/server-update-pending") else {
    raise AdapterError("Server update is incomplete; retry the update")
  }
  let pending = directory + "/server-relay-pending"
  errdefer save_diagnostic(
    "server-relay-sync",
    "failed",
    error_type="sync_failed",
    tunnel_directory=directory,
    recording=workspace_recording(state),
  )
  let output = if !connection_result && server_is_running(state) {
    let observed = server_relay_check(state, "verify", "server-relay-check")
    let outcome = if observed == "mismatch" {
      @fs.write_file(pending, "", permission=0o600)
      server_relay_check(state, "sync", "server-relay-stop")
    } else {
      observed
    }
    if outcome == "restart" {
      ignore(launch_server(state))
      let verified = server_relay_check(state, "verify", "server-relay-verify")
      guard verified == "match" else {
        raise AdapterError("Orca Server relay instance changed during restart")
      }
      save_diagnostic(
        "server-relay-sync",
        "restarted",
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
    } else if outcome != "match" && outcome != "skip" {
      raise AdapterError("Cannot compare Orca Server relay instance")
    }
    if @fs.exists(pending) {
      guard outcome != "skip" else {
        raise AdapterError(
          "Orca Server relay instance unavailable after restart",
        )
      }
      @fs.remove(pending)
    }
    save_diagnostic(
      "recover-server",
      if outcome == "restart" {
        "restart"
      } else {
        "reuse"
      },
      tunnel_directory=directory,
      recording=workspace_recording(state),
    )
    Json::null()
  } else {
    save_diagnostic(
      "recover-server",
      "start",
      tunnel_directory=directory,
      recording=workspace_recording(state),
    )
    if field(state, "orcaVolume") is Some(_) {
      prepare_orca_storage(state)
      let installation = remote(
          state, "if test -x \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\"; then printf installed; else printf missing; fi",
          "orca-install-probe",
        )
        .trim()
        .to_owned()
      match installation {
        "installed" => ()
        "missing" =>
          ignore(remote(state, server_install_script(), "orca-install"))
        _ => raise AdapterError("Invalid Orca installation probe result")
      }
    }
    let output = launch_server(state)
    if @fs.exists(pending) {
      let verified = server_relay_check(state, "verify", "server-relay-verify")
      guard verified == "match" else {
        raise AdapterError("Orca Server relay instance changed during restart")
      }
      @fs.remove(pending)
      save_diagnostic(
        "server-relay-sync",
        "restarted",
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
    }
    configure_orca_project(state)
    output
  }
  @fs.write_file(directory + "/server-enabled", "", permission=0o600)
  output
}

///|
async fn launch_server(state : Json, update_marker? : (String, String)) -> Json {
  let root = required(state, "projectRoot")
  let port = reserve_server_port(state)
  let configured_env = field(state, "serverEnv").unwrap_or(Json::empty_object())
  let diagnostic_env = Json::empty_object()
  if configured_env is Json::Object(values) {
    for name, value in values {
      if value is Json::String(text) {
        set_field(diagnostic_env, name, Json::string(redact_credentials(text)))
      }
    }
  }
  let recording = workspace_recording(state)
  let launch = (if field(state, "orcaVolume") is Some(_) {
      "export ORCA_USER_DATA_PATH=/workspaces/.orca/.profile; "
    } else {
      ""
    }) +
    server_launch_script(root, port, configured_env, recording~, update_marker?)
  let script = if update_marker is Some(_) {
    server_update_locked(launch)
  } else {
    launch
  }
  let (status, raw_output, detail) = command_result(
    workspace_program(state, "ssh"),
    mux_ssh_args(state) + [script],
    "orca-serve",
    environment=workspace_environment(state),
    cwd?=workspace_directory(state).map(path => path[:]),
  )
  let mut output = raw_output
  if recording {
    let mut observed = None
    let mut truncated = Json::array([])
    let mut observation_error = false
    if raw_output.split_once("\n") is Some((first, remaining)) {
      let event = @json.parse(first.to_owned()) catch { _ => Json::null() }
      if field(event, "kind") == Some(Json::string("result")) &&
        field(event, "serverEnvironment") is Some(value) {
        observed = Some(value)
        truncated = field(event, "truncated").unwrap_or(Json::array([]))
        observation_error = field(event, "observationError") ==
          Some(Json::boolean(true))
        output = remaining.to_owned()
      }
    }
    let complete = (
        configured_env == Json::empty_object() || observed is Some(_)
      ) &&
      truncated == Json::array([]) &&
      !observation_error
    save_diagnostic(
      "server-environment",
      if complete {
        "observed"
      } else {
        "partial"
      },
      evidence={
        "templates": diagnostic_env,
        "references": observed.unwrap_or(Json::null()),
        "completeness": if complete {
          "complete"
        } else {
          "partial"
        },
        "missingReason": if complete {
          Json::null()
        } else if observed is None || observation_error {
          "observation_failed"
        } else {
          "value_truncated"
        },
        "truncatedReferences": truncated,
      },
      recording~,
    )
  }
  guard status == 0 else {
    raise AdapterError(command_failure("orca-serve", status, detail))
  }
  let result = @json.parse(output)
  let connection = match field(result, "connection") {
    Some(value) => value
    None => result
  }
  guard required(connection, "pairingCode") != "" else {
    raise AdapterError("Orca returned no pairing code")
  }
  @fs.write_file(
    required(state, "tunnelDirectory") + "/pairing-code",
    required(connection, "pairingCode"),
    permission=0o600,
  )
  let output : Json = {
    "type": "orca-server",
    "pairingCode": required(connection, "pairingCode"),
    "projectRoot": root,
  }
  output
}

