///|
fn repository_slug(repository : String) -> String {
  let raw_name = repository
    .trim_end(chars="/")
    .split("/")
    .to_array()
    .last()
    .unwrap()
    .split(":")
    .to_array()
    .last()
    .unwrap()
    .to_owned()
  let name = raw_name
    .strip_suffix(".git")
    .unwrap_or(raw_name)
    .to_owned()
    .to_lower()
  let slug = StringBuilder()
  let mut separator = false
  let mut started = false
  for c in name {
    if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') {
      if separator && started {
        slug.write_string("-")
      }
      slug.write_char(c)
      separator = false
      started = true
    } else {
      separator = true
    }
  }
  let slug = slug.to_string()
